import{_ as r,l,o as e,c as n,v as t,p as s,x as i,d,i as p,S as m}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"MIMO 与速率自适应","description":"","frontmatter":{"title":"MIMO 与速率自适应","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/mimo-rate-adaptation.md","filePath":"cs/mimo-rate-adaptation.md","lastUpdated":1789023840000}'),M={name:"cs/mimo-rate-adaptation.md"};function c(h,a,E,_,A,S){const o=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="mimo-与速率自适应" tabindex="-1">MIMO 与速率自适应 <a class="header-anchor" href="#mimo-与速率自适应" aria-label="Permalink to &quot;MIMO 与速率自适应&quot;">​</a></h1><div class="epigraph"><p>多天线把空间当新的自由度：流数受秩限制；速率自适应则按瞬时 SNR 选 MCS，使工作点跟着衰落走。</p><footer>—— 据 Telatar, Capacity of Multi-antenna Channels, ETT 1999；IEEE 802.11n/ac 整理</footer></div><p><a href="/cs/wifi-frames-ofdm">上一课</a>给出 OFDM 与 MCS 阶梯。缺口是<strong>空间复用与怎么爬阶梯</strong>：MIMO 把 \\(C\\) 近似写成 \\(\\sum\\log(1+\\lambda_i\\mathrm{SNR})\\)；自适应用探测与统计选调制编码。本课不把 Wi‑Fi 6 的 RU 调度写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单天线 OFDM 已用尽该 \\(B\\) 下的频率自由度。多天线：信道矩阵 \\(H\\) 的奇异值给出并行流。11n 起数据口走空时编码或 SDM。自适应：若固定 64-QAM，深衰落就爆错；降到 QPSK 保住连通。探帧、块确认统计、或闭环 CSI（11ac/ax 更重）驱动降阶/升阶。有线自协商几乎一次定终身；无线每毫秒都可能改 MCS。</p><p>不要把天线数写成容量线性倍数：相关与秩不足时流数上不去。</p><p><span class="marginnote">Telatar 与 Foschini 给出高斯 MIMO 容量。802.11 实现是离散 MCS 表。本课不推注水功率分配全文。</span></p><h3 id="天线数不是容量倍数" tabindex="-1">天线数不是容量倍数 <a class="header-anchor" href="#天线数不是容量倍数" aria-label="Permalink to &quot;天线数不是容量倍数&quot;">​</a></h3><p>秩不足则流数上不去。有线自协商几乎一次定终身；无线 MCS 持续跟踪。碰撞会被误读成差信道。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：开环（STBC 稳）vs 闭环（波束、预编码）。画：估计 \\(H\\) → 选流数与 MCS → 发 → 看 PER → 调。有线 PAM-4 降阶是同类，只是时间尺度不同。</p>',11)),(e(),s(m,null,{default:i(()=>[p(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20H%5B%22%E4%BF%A1%E9%81%93%E7%9F%A9%E9%98%B5%20H%22%5D%20--%3E%20RANK%5B%22%E5%8F%AF%E7%94%A8%E6%B5%81%E6%95%B0%22%5D%0A%20%20RANK%20--%3E%20MCS%5B%22%E9%80%89%E8%B0%83%E5%88%B6%E7%BC%96%E7%A0%81%22%5D%0A%20%20MCS%20--%3E%20PER%5B%22%E5%9D%97%E7%A1%AE%E8%AE%A4%2F%E8%AF%AF%E5%8C%85%22%5D%0A%20%20PER%20--%3E%20MCS%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AP 与客户端能力取交，类似自协商，但之后仍自适应。LACP 哈希与 MIMO 流无关：流在 PHY，哈希在桥。PFC 很少用在无线跳上。容量仍是上界；MCS 是带 PER 约束的离散点。</p><p>隐终端与自适应叠加：碰撞被当成「信道差」会误降速，协议用 RTS/CTS 或调度减轻。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MU-MIMO 用户选择算法的全部。Wi‑Fi 6 OFDMA 是下一课。后课默认：MIMO 给空间自由度；自适应跟踪衰落。</p><p>不要把「8×8」广告当室内总能 8 流。</p><p>上一课留下的缺口在本课收口；「MIMO 与速率自适应」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/wifi6-ofdma">WiFi 6 / 7 与 OFDMA</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MIMO 容量由信道秩与奇异值决定。</li><li>MCS 自适应是离散逼近瞬时 \\(C\\)。</li><li>碰撞会污染速率估计。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Telatar, 1999；IEEE 802.11n/ac。</li></ul>',10))])}const u=r(M,[["render",c]]);export{C as __pageData,u as default};
